#!/usr/bin/env bash
# 025 -- (1) testes da futura V1.0.274 numa copia do codigo instalado em /tmp; (2) RECONSTRUCAO (criterio 3.1 do pedido):
# com o codigo novo e o estado REAL so na memoria (nada gravado), cada reserva futura/em curso do Airbnb que tem e-mail e
# tirada da memoria e o plano diz se o e-mail a criaria igual (datas, hospedes, categoria, unidade livre). So contagens.
set -u
exec 2>&1
T=$(mktemp -d /tmp/v274.XXXX); chmod 755 $T
echo "" | base64 -d > $T/v274.patch
echo "9bf5e8a99bee804aed394a8e2ab190bdaefd79fae8b4bb2e0029e84b43486f32  $T/v274.patch" | sha256sum -c --quiet || { echo "pacote corrompido"; exit 1; }
mkdir -p $T/repo && cd /opt/PMS-Banana-AI && tar cf - --exclude=.venv --exclude=__pycache__ --exclude='*.pyc' --exclude=node_modules SISTEMA 2>/dev/null | (cd $T/repo && tar xf -)
cd $T/repo && patch -p1 -s --no-backup-if-mismatch < $T/v274.patch && echo "copia 1.0.273 + pacote 274: ok"
chmod -R a+rX $T
VENV=/opt/PMS-Banana-AI/SISTEMA/.venv
cd $T/repo/SISTEMA
P() { env -i PATH=/usr/local/bin:/usr/bin:/bin HOME=$T LANG=C.UTF-8 PYTHONDONTWRITEBYTECODE=1 timeout 400 $VENV/bin/pytest -o addopts="-p no:cacheprovider" "$@" 2>&1; }
echo "== testes novos + entrada + channel + reservation"
P -q api/app/entrada api/app/channel api/app/reservation | grep -E '^(FAILED|ERROR)|[0-9]+ (passed|failed)' | tail -25 | cut -c1-200
echo "== reconstrucao com o estado real (so memoria)"
cd $T/repo/SISTEMA/api
sudo -n /opt/esteira-nuvem/com-segredos env PMS_TRANSCRICAO_AQUECER=off PYTHONDONTWRITEBYTECODE=1 timeout 400 $VENV/bin/python -u - <<'PY' 2>&1 | grep -vE '^(WARNING|INFO|DEBUG)'
import email, imaplib, os
from collections import Counter
from datetime import datetime, timedelta, timezone
from email.utils import parseaddr, parsedate_to_datetime
import app.versao as V
from app.main import build_state
from app.entrada import imap_reservas as I, airbnb_email as A, airbnb_reservas as AR
from app.entrada.anuncios_airbnb import CATEGORIAS
from app.entrada.intents import classificar, ota_do_dominio, casar
print("codigo carregado:", V.VERSAO, "· de", os.path.dirname(AR.__file__)[-40:])
st = build_state(); s = st.store; agora = datetime.now(timezone.utc); hoje = agora.date()
cfg = I.config(os.environ); print("pastas (padrao novo, sem a chave do servidor):", I.PASTAS)
M = imaplib.IMAP4_SSL(cfg["servidor"], 993, timeout=30); M.login(cfg["usuario"], cfg["senha"])
M.select('"INBOX.03_Reservas"', readonly=True)
typ, d = M.search(None, f"(SINCE {(agora - timedelta(days=150)).strftime('%d-%b-%Y')})")
leituras = {}
for n in (d[0] or b"").split():
    t, c = M.fetch(n, "(BODY.PEEK[HEADER.FIELDS (FROM)])")
    if ota_do_dominio(parseaddr(I._dec(email.message_from_bytes(c[0][1]).get("From")))[1].lower().rsplit("@", 1)[-1]) != "Airbnb": continue
    t, c = M.fetch(n, "(BODY.PEEK[])"); em = I.para_porta(c[0][1])
    if (classificar(em["dominio"], em["assunto"], em["texto"]).get("tipo")) != "reserva_nova": continue
    try: q = parsedate_to_datetime(em["quando"])
    except Exception: q = None
    lt = A.ler(em["assunto"], em["texto"], q); lt.pop("_nome", None)
    if lt.get("codigo"): leituras[lt["codigo"]] = lt
M.logout()
def cat_de(u):
    return next((c for c, us in CATEGORIAS.items() if u in us), "?")
fut = [r for r in s.reservations.values() if r.checkout and r.checkout >= hoje and str(getattr(r.status, "value", r.status)) not in ("cancelled", "no_show")
       and (r.ota_code or "").startswith("HM")]
res = Counter(); faltas = Counter(); mudou_unidade = Counter()
for r in fut:
    lt = leituras.get(r.ota_code)
    if lt is None: res["sem e-mail de reserva nova"] += 1; continue
    ev = s.events.get(r.reservation_id)
    k = next(k for k, x in s.reservations.items() if x is r)
    s.reservations.pop(k); evs = {kk: e for kk, e in list(s.events.items()) if kk == r.reservation_id or str(e.event_id).startswith(f"event-{r.reservation_id}-")}
    for kk in evs: s.events.pop(kk)
    try:
        p = AR.plano(s, {"ota": "Airbnb", "tipo": "reserva_nova", "codigo": r.ota_code}, lt)
    finally:
        s.reservations[k] = r; s.events.update(evs)
    if p["acao"] != "criar":
        res["NAO criaria"] += 1; faltas[p["motivo"].split(": ", 1)[-1][:60]] += 1; continue
    igual = (p["checkin"] == r.checkin.isoformat(), p["checkout"] == r.checkout.isoformat(), p["hospedes"] == int(r.paid_occupancy))
    if not all(igual): res["criaria com " + "/".join(n for n, ok in zip(("check-in", "checkout", "hospedes"), igual) if not ok) + " diferente(s)"] += 1; continue
    u_atual = (ev.where[0] if ev is not None and ev.where else "")
    res["criaria igual"] += 1
    if cat_de(p["unidade"]) != cat_de(u_atual): mudou_unidade["categoria diferente da estadia atual"] += 1
    elif p["unidade"] != u_atual: mudou_unidade["mesma categoria, outra unidade (a distribuicao das 6h decide)"] += 1
    else: mudou_unidade["mesma unidade"] += 1
print("reservas futuras/em curso do Airbnb no sistema:", len(fut))
print("resultado:", dict(res)); print("por que nao:", dict(faltas)); print("unidade:", dict(mudou_unidade))
PY
rm -rf $T
